namespace App\Repositories\Eloquent;
use App\Models\Brand;
use App\Repositories\Interfaces\BrandRepositoryInterface;
class BrandRepository extends BaseRepository implements BrandRepositoryInterface
{
    /**
     * BrandRepository constructor.
     *
     * @param Brand $model
     */
    public function __construct(Brand $model)
    {
        parent::__construct($model);
    }
    /**
     * @inheritDoc
     */
    public function getFilteredBrands(array $filters, $perPage = 10)
    {
        $query = $this->model->query();
        // Apply search filter
        if (isset($filters['search'])) {
            $searchTerm = $filters['search'];
            $query->where(function ($q) use ($searchTerm) {
                $q->where('name_vn', 'LIKE', "%{$searchTerm}%")
                  ->orWhere('status', '=', $searchTerm === 'active' ? 1 : 0);
            });
        }
        // Apply sorting
        $sortField = $filters['sort_field'] ?? 'stt';
        $sortDirection = $filters['sort_direction'] ?? 'asc';
        $query->orderBy($sortField, $sortDirection);
        return $query->paginate($perPage);
    }
    /**
     * @inheritDoc
     */
    public function getActiveBrands()
    {
        return $this->model->where('status', 1)
            ->orderBy('stt', 'asc')
            ->get();
    }
    /**
     * @inheritDoc
     */
    public function updateOrder($uuid, $order)
    {
        return $this->model->where('uuid', $uuid)->update(['stt' => $order]);
    }
}<?php
namespace App\Repositories\Eloquent;
use App\Models\CateNew;
use App\Repositories\Interfaces\CateNewRepositoryInterface;
use App\Services\SlugService;
use Illuminate\Support\Str;
class CateNewRepository extends BaseRepository implements CateNewRepositoryInterface
{
    protected $slugService;
    /**
     * CateNewRepository constructor.
     *
     * @param CateNew $model
     * @param SlugService $slugService
     */
    public function __construct(CateNew $model, SlugService $slugService)
    {
        parent::__construct($model);
        $this->slugService = $slugService;
    }
    /**
     * @inheritDoc
     */
    public function getFilteredCategories(array $filters, $perPage = 10)
    {
        $query = $this->model->query();
        // Search filter
        if (isset($filters['search'])) {
            $searchTerm = $filters['search'];
            $query->where(function ($q) use ($searchTerm) {
                $q->where('name_vn', 'LIKE', "%{$searchTerm}%")
                    ->orWhere('status', '=', $searchTerm === 'active' ? 1 : 0);
            });
        }
        // Parent filter
        if (isset($filters['parent_id'])) {
            $query->where('parent_id', $filters['parent_id']);
        }
        // Sorting
        $sortField = $filters['sort_field'] ?? 'stt';
        $sortDirection = $filters['sort_direction'] ?? 'asc';
        $query->orderBy($sortField, $sortDirection);
        return $query->select('uuid', 'name_vn', 'name_en', 'slug_vn', 'slug_en', 'status', 'parent_id', 'stt', 'image_vn', 'image_en', 'created_at', 'id_cate_new')->orderBy('created_at', 'desc')
            ->paginate($perPage);
    }
    /**
     * @inheritDoc
     */
    public function getActiveParentCategories()
    {
        return $this->model->where('status', 1)
            ->where('parent_id', 0)
            ->orderBy('stt', 'asc')
            ->get();
    }
    public function getCategoriesWithChildren()
    {
        return $this->model->with('children')
            ->where('parent_id', 0)
            ->orderBy('stt', 'asc')
            ->get();
    }
}<?php
namespace App\Repositories\Eloquent;
use App\Models\CateProduct;
use App\Repositories\Interfaces\CateProductRepositoryInterface;
use App\Services\SlugService;
use Illuminate\Support\Str;
class CateProductRepository extends BaseRepository implements CateProductRepositoryInterface
{
    protected $slugService;
    /**
     * CateProductRepository constructor.
     *
     * @param CateProduct $model
     * @param SlugService $slugService
     */
    public function __construct(CateProduct $model, SlugService $slugService)
    {
        parent::__construct($model);
        $this->slugService = $slugService;
    }
    /**
     * @inheritDoc
     */
    public function getFilteredCategories(array $filters, $perPage = 10)
    {
        $query = $this->model->query();
        // Search filter
        if (isset($filters['search'])) {
            $searchTerm = $filters['search'];
            $query->where(function ($q) use ($searchTerm) {
                $q->where('name_vn', 'LIKE', "%{$searchTerm}%")
                    ->orWhere('status', '=', $searchTerm === 'active' ? 1 : 0);
            });
        }
        // Parent filter
        if (isset($filters['parent_id'])) {
            $query->where('parent_id', $filters['parent_id']);
        }
        // Sorting
        $sortField = $filters['sort_field'] ?? 'stt';
        $sortDirection = $filters['sort_direction'] ?? 'asc';
        $query->orderBy($sortField, $sortDirection);
        return $query->select('uuid', 'name_vn', 'name_en', 'slug_vn', 'slug_en', 'status', 'home', 'parent_id', 'stt', 'image_vn', 'image_en', 'created_at', 'id_cate_product')->orderBy('created_at', 'desc')
            ->paginate($perPage);
    }
    /**
     * @inheritDoc
     */
    public function getActiveParentCategories()
    {
        return $this->model->where('status', 1)
            ->where('parent_id', 0)
            ->orderBy('stt', 'asc')
            ->get();
    }
    public function getCategoriesWithChildren()
    {
        return $this->model->with('children')
            ->where('parent_id', 0)
            ->orderBy('stt', 'asc')
            ->get();
    }
}<?php
namespace App\Repositories\Eloquent;
use App\Models\ChatSession;
use App\Models\ChatMessage;
use App\Repositories\Interfaces\ChatRepositoryInterface;
use Illuminate\Support\Str;
use Illuminate\Support\Facades\Log;
class ChatRepository extends BaseRepository implements ChatRepositoryInterface
{
    /**
     * ChatRepository constructor.
     *
     * @param ChatSession $model
     */
    public function __construct(ChatSession $model)
    {
        parent::__construct($model);
    }
    public function getActiveSessions($perPage = 15)
    {
        return $this->model
            ->with(['user', 'latestMessage'])
            ->active()
            ->orderBy('last_message_at', 'desc')
            ->paginate($perPage);
    }
    // BỎ method findByUuid() đi - dùng của BaseRepository
    /**
     * @inheritDoc
     */
    public function getOrCreateSession(array $data)
    {
        Log::info('ChatRepository getOrCreateSession', [
            'data' => $data,
            'has_user_id' => isset($data['user_id']),
            'has_session_id' => isset($data['session_id']),
        ]);
        // For registered users
        if (isset($data['user_id']) && $data['user_id']) {
            $session = $this->model
                ->where('user_id', $data['user_id'])
                ->where('status', 'active')
                ->latest()
                ->first();
            if (!$session) {
                $session = $this->model->create([
                    'user_id' => $data['user_id'],
                    'session_id' => $data['session_id'] ?? 'user-' . $data['user_id'] . '-' . uniqid(),
                    'uuid' => Str::uuid(),
                    'status' => 'active',
                    'last_message_at' => now(),
                ]);
                Log::info('New user session created', [
                    'session_id' => $session->id,
                    'uuid' => $session->uuid,
                    'user_id' => $session->user_id,
                ]);
            }
            return $session;
        }
        // For guest users - check by session_id
        if (isset($data['session_id']) && $data['session_id']) {
            $session = $this->model
                ->where('session_id', $data['session_id'])
                ->where('status', 'active')
                ->latest()
                ->first();
            if (!$session) {
                $session = $this->model->create([
                    'user_id' => null,
                    'guest_name' => $data['guest_name'] ?? null,
                    'guest_email' => $data['guest_email'] ?? null,
                    'session_id' => $data['session_id'],
                    'uuid' => Str::uuid(),
                    'status' => 'active',
                    'last_message_at' => now(),
                ]);
                Log::info('New guest session created', [
                    'session_id' => $session->id,
                    'uuid' => $session->uuid,
                    'guest_name' => $session->guest_name,
                    'guest_email' => $session->guest_email,
                ]);
            }
            return $session;
        }
        // Create new guest session without session_id (fallback)
        $session = $this->model->create([
            'user_id' => null,
            'guest_name' => $data['guest_name'] ?? null,
            'guest_email' => $data['guest_email'] ?? null,
            'session_id' => 'guest-' . uniqid(),
            'uuid' => Str::uuid(),
            'status' => 'active',
            'last_message_at' => now(),
        ]);
        Log::info('New guest session created (fallback)', [
            'session_id' => $session->id,
            'uuid' => $session->uuid,
        ]);
        return $session;
    }
    /**
     * @inheritDoc
     */
    public function sendMessage($sessionUuid, array $messageData)
    {
        // Sử dụng findByUuid từ BaseRepository
        $session = $this->findByUuid($sessionUuid);
        if (!$session) {
            Log::error('ChatRepository sendMessage: Session not found', [
                'session_uuid' => $sessionUuid,
                'message_data' => $messageData,
            ]);
            throw new \Exception('Chat session not found');
        }
        Log::info('ChatRepository sendMessage: Session found', [
            'session_uuid' => $sessionUuid,
            'session_id' => $session->id,
            'session_user_id' => $session->user_id,
            'is_guest' => $session->user_id === null,
            'sender_type' => $messageData['sender_type'],
            'sender_id' => $messageData['sender_id'] ?? 'NULL',
        ]);
        // Create message - sender_id có thể NULL cho guest
        $message = ChatMessage::create([
            'session_id' => $session->id,
            'session_uuid' => $session->uuid,
            'sender_type' => $messageData['sender_type'],
            'sender_id' => $messageData['sender_id'] ?? null,
            'message' => $messageData['message'],
            'uuid' => Str::uuid(),
            'is_read' => $messageData['is_read'] ?? false,
        ]);
        // Update session's last_message_at
        $session->update(['last_message_at' => now()]);
        Log::info('Message created successfully', [
            'message_id' => $message->id,
            'message_uuid' => $message->uuid,
            'sender_id' => $message->sender_id,
        ]);
        return $message->load('session');
    }
    /**
     * @inheritDoc
     */
    public function markMessagesAsRead($sessionUuid, $senderType = 'user')
    {
        $session = $this->findByUuid($sessionUuid);
        if (!$session) {
            return 0;
        }
        return ChatMessage::where('session_id', $session->id)
            ->where('sender_type', $senderType)
            ->where('is_read', false)
            ->update(['is_read' => true]);
    }
    /**
     * @inheritDoc
     */
    public function getUnreadMessagesCount()
    {
        return ChatMessage::where('sender_type', 'user')
            ->where('is_read', false)
            ->count();
    }
    /**
     * @inheritDoc
     */
    public function closeSession($sessionUuid)
    {
        $session = $this->findByUuid($sessionUuid);
        if (!$session) {
            return false;
        }
        return $session->update(['status' => 'closed']);
    }
    /**
     * Get messages for a session
     *
     * @param string $sessionUuid
     * @param int $limit
     * @return \Illuminate\Database\Eloquent\Collection
     */
    public function getSessionMessages($sessionUuid, $limit = 50)
    {
        $session = $this->findByUuid($sessionUuid);
        if (!$session) {
            return collect();
        }
        return ChatMessage::where('session_id', $session->id)
            ->with('sender:id,fullname')
            ->orderBy('created_at', 'asc')
            ->limit($limit)
            ->get();
    }
    /**
     * Get sessions with unread messages
     *
     * @return \Illuminate\Database\Eloquent\Collection
     */
    public function getSessionsWithUnreadMessages()
    {
        return $this->model
            ->with(['user', 'latestMessage'])
            ->withUnreadMessages()
            ->active()
            ->orderBy('last_message_at', 'desc')
            ->get();
    }
    /**
     * Find session by session_id (UUID) or id (for backward compatibility)
     *
     * @param string|int $sessionId
     * @return \App\Models\ChatSession|null
     */
    public function findBySessionId($sessionId)
    {
        // If it's a UUID, find by session_id
        if (preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/', $sessionId)) {
            return $this->model->where('session_id', $sessionId)->first();
        }
        // If it's numeric, find by id
        if (is_numeric($sessionId)) {
            return $this->find($sessionId);
        }
        // Otherwise, find by session_id string (for legacy sessions)
        return $this->model->where('session_id', $sessionId)->first();
    }
    /**
     * Create a new session
     *
     * @param array $data
     * @return \App\Models\ChatSession
     */
    public function createSession(array $data)
    {
        return $this->model->create([
            'user_id' => $data['user_id'] ?? null,
            'guest_name' => $data['guest_name'] ?? null,
            'guest_email' => $data['guest_email'] ?? null,
            'session_id' => $data['session_id'] ?? Str::uuid(),
            'uuid' => Str::uuid(),
            'status' => 'active',
            'last_message_at' => now(),
        ]);
    }
}<?php
namespace App\Repositories\Eloquent;
use App\Models\Comment;
use App\Repositories\Interfaces\CommentRepositoryInterface;
class CommentRepository extends BaseRepository implements CommentRepositoryInterface
{
    public function __construct(Comment $model)
    {
        parent::__construct($model);
    }
    /**
     * Get filtered comments with pagination
     *
     * @param array $filters
     * @param int $perPage
     * @return \Illuminate\Pagination\LengthAwarePaginator
     */
    public function getFilteredComments(array $filters, $perPage = 10)
    {
        $query = $this->model->newQuery();
        // Search filter
        if (!empty($filters['search'])) {
            $search = $filters['search'];
            $query->where(function ($q) use ($search) {
                $q->where('name', 'like', "%{$search}%")
                  ->orWhere('email', 'like', "%{$search}%")
                  ->orWhere('content', 'like', "%{$search}%");
            });
        }
        // Status filter
        if (isset($filters['status']) && $filters['status'] !== '') {
            $query->where('status', $filters['status']);
        }
        // Type filter
        if (!empty($filters['type'])) {
            // Convert type string to type_post number for filtering
            $typePost = $filters['type'] === 'news' ? 1 : ($filters['type'] === 'product' ? 2 : 3);
            $query->where('type_post', $typePost);
        }
        // Sorting
        $sortField = $filters['sort_field'] ?? 'created_at';
        $sortDirection = $filters['sort_direction'] ?? 'desc';
        $query->orderBy($sortField, $sortDirection);
        return $query->paginate($perPage);
    }
    /**
     * Get approved comments for frontend display
     *
     * @param string $type
     * @param int $itemId
     * @return \Illuminate\Database\Eloquent\Collection
     */
    public function getApprovedCommentsForItem($type, $itemId)
    {
        // Convert type string to type_post number
        $typePost = $type === 'news' ? 1 : 2;
        return $this->model->approved()
                          ->byItem($typePost, $itemId)
                          ->orderBy('created_at', 'desc')
                          ->get();
    }
    /**
     * Create a new comment
     *
     * @param array $data
     * @return Comment
     */
    public function createComment(array $data)
    {
        return $this->model->create($data);
    }
}<?php
