namespace App\Services;
use Illuminate\Support\Facades\Cache;
class CacheService
{
    /**
     * Cache tags for different modules
     */
    const TAGS = [
        'frontend' => 'frontend',
        'admin' => 'admin',
        'website' => 'website',
        'menu' => 'menu',
        'categories' => 'categories',
        'products' => 'products',
        'news' => 'news',
        'brands' => 'brands',
        'features' => 'features',
        'sliders' => 'sliders',
        'galleries' => 'galleries',
        'pages' => 'pages',
        'users' => 'users',
        'orders' => 'orders',
        'comments' => 'comments',
        'contacts' => 'contacts',
        'feedback' => 'feedback',
        'search' => 'search',
        'system' => 'system',
    ];
    /**
     * Default cache TTL in minutes
     */
    const TTL = [
        'short' => 15,    // 15 minutes
        'medium' => 60,   // 1 hour
        'long' => 360,    // 6 hours
        'day' => 1440,    // 24 hours
    ];
    /**
     * Remember cache with tags
     *
     * @param string $tag
     * @param string $key
     * @param int $ttl
     * @param callable $callback
     * @return mixed
     */
    public static function remember(string $tag, string $key, int $ttl, callable $callback)
    {
        if (Cache::supportsTags()) {
            return Cache::tags([$tag])->remember($key, $ttl, $callback);
        } else {
            return Cache::remember($key, $ttl, $callback);
        }
    }
    /**
     * Forget cache by tag
     *
     * @param string $tag
     * @return bool
     */
    public static function forgetTag(string $tag): bool
    {
        if (Cache::supportsTags()) {
            return Cache::tags([$tag])->flush();
        } else {
            // For non-tagged caches, we can't flush by tag, so return true
            return true;
        }
    }
    /**
     * Forget multiple tags
     *
     * @param array $tags
     * @return bool
     */
    public static function forgetTags(array $tags): bool
    {
        foreach ($tags as $tag) {
            self::forgetTag($tag);
        }
        return true;
    }
    /**
     * Forget cache by key in specific tag
     *
     * @param string $tag
     * @param string $key
     * @return bool
     */
    public static function forget(string $tag, string $key): bool
    {
        if (Cache::supportsTags()) {
            return Cache::tags([$tag])->forget($key);
        } else {
            return Cache::forget($key);
        }
    }
    /**
     * Get cache TTL by type
     *
     * @param string $type
     * @return int
     */
    public static function getTtl(string $type = 'medium'): int
    {
        return self::TTL[$type] ?? self::TTL['medium'];
    }
    /**
     * Clear all cache (use with caution)
     *
     * @return bool
     */
    public static function clearAll(): bool
    {
        return Cache::flush();
    }
    /**
     * Get cache size for a tag (if supported by cache driver)
     *
     * @param string $tag
     * @return int
     */
    public static function getTagSize(string $tag): int
    {
        if (Cache::supportsTags()) {
            try {
                $store = Cache::tags([$tag])->getStore();
                if (is_object($store) && method_exists($store, 'getSize')) {
                    return (int) call_user_func([$store, 'getSize']);
                }
                return 0;
            } catch (\Exception $e) {
                return 0;
            }
        } else {
            return 0;
        }
    }
}<?php
namespace App\Services;
use App\Models\Product;
use Illuminate\Http\Request;
class CartService
{
    /**
     * Get cart from session
     *
     * @return array
     */
    public function getCart(): array
    {
        return session()->get('cart', []);
    }
    /**
     * Check if cart is empty
     *
     * @return bool
     */
    public function isEmpty(): bool
    {
        return count($this->getCart()) === 0;
    }
    /**
     * Add product to cart
     *
     * @param Request $request
     * @param string $uuid
     * @param int $quantity
     * @return bool
     */
    public function addProduct(Request $request, string $uuid, int $quantity = 1): bool
    {
        if ($request->quantity) {
            $quantity = $request->quantity;
        }
        // Validate quantity
        if ($quantity <= 0 || $quantity > 999) {
            return false;
        }
        $product = Product::with('cate')->where('uuid', $uuid)->first();
        if (!$product) {
            return false;
        }
        $this->addToCartSession($quantity, $product);
        return true;
    }
    /**
     * Add product to cart session
     *
     * @param int $quantity
     * @param Product $product
     * @return void
     */
    private function addToCartSession(int $quantity, Product $product): void
    {
        $cart = session()->get('cart', []);
        $found = false;
        foreach ($cart as $key => $item) {
            if ($item['uuid'] === $product->uuid) {
                $cart[$key]['qty'] += $quantity;
                $found = true;
                break;
            }
        }
        if (!$found) {
            $cart[] = [
                'stt' => count($cart) + 1,
                'id_product' => $product->id_product,
                'name_vn' => $product->name_vn,
                'name_en' => $product->name_en,
                'qty' => $quantity,
                'price' => $product->price,
                'price_old' => $product->price_old,
                'avatar' => $product->image,
                'uuid' => $product->uuid,
                'name_cate' => $product->cate->name_vn ?? '',
                'slug' => $product->slug,
                'slug_cate' => $product->cate->slug ?? '',
            ];
        }
        session()->put('cart', $cart);
    }
    /**
     * Update cart quantities
     *
     * @param Request $request
     * @return void
     */
    public function updateCart(Request $request): void
    {
        $cart = session()->get('cart', []);
        foreach ($request->qty as $stt => $quantity) {
            foreach ($cart as &$item) {
                if ($item['stt'] == $stt) {
                    $item['qty'] = $quantity;
                    break;
                }
            }
        }
        session()->put('cart', $cart);
    }
    /**
     * Remove item from cart
     *
     * @param string $uuid
     * @param int $stt
     * @return bool
     */
    public function removeItem(string $uuid, int $stt): bool
    {
        $cart = session()->get('cart', []);
        foreach ($cart as $key => $item) {
            if ($item['uuid'] === $uuid && $item['stt'] === $stt) {
                unset($cart[$key]);
                session()->put('cart', $cart);
                return true;
            }
        }
        return false;
    }
    /**
     * Clear entire cart
     *
     * @return void
     */
    public function clearCart(): void
    {
        session()->forget('cart');
    }
    /**
     * Get cart total items count
     *
     * @return int
     */
    public function getTotalItems(): int
    {
        $cart = $this->getCart();
        return array_sum(array_column($cart, 'qty'));
    }
    /**
     * Get cart total price
     *
     * @return float
     */
    public function getTotalPrice(): float
    {
        $cart = $this->getCart();
        $total = 0;
        foreach ($cart as $item) {
            $total += $item['price'] * $item['qty'];
        }
        return $total;
    }
}<?php
namespace App\Services;
use App\Models\Comment;
use App\Repositories\Interfaces\CommentRepositoryInterface;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Validator;
class CommentService
{
    protected $commentRepository;
    public function __construct(CommentRepositoryInterface $commentRepository)
    {
        $this->commentRepository = $commentRepository;
    }
    /**
     * Get approved comments for an item (news/product)
     *
     * @param string $type
     * @param int $itemId
     * @return \Illuminate\Database\Eloquent\Collection
     */
    public function getApprovedCommentsForItem($type, $itemId)
    {
        return $this->commentRepository->getApprovedCommentsForItem($type, $itemId);
    }
    /**
     * Create a new comment
     *
     * @param array $data
     * @return array
     */
    public function createComment(array $data)
    {
        // Validate data
        $validator = Validator::make($data, [
            'type' => 'required|in:news,product',
            'item_id' => 'required|integer',
            'content' => 'required|string|max:1000',
            'name' => 'required|string|max:255',
            'email' => 'required|email|max:255',
            'rating' => 'nullable|integer|min:1|max:5', // Rating chỉ cho product
        ]);
        if ($validator->fails()) {
            return [
                'success' => false,
                'message' => 'Dữ liệu không hợp lệ',
                'errors' => $validator->errors()
            ];
        }
        try {
            // Convert type to type_post number
            $data['type_post'] = $data['type'] === 'news' ? 1 : 2;
            $data['id_post'] = $data['item_id'];
            // Remove new format fields
            unset($data['type'], $data['item_id']);
            // Set default status to 0 (pending approval)
            $data['status'] = 0;
            $comment = $this->commentRepository->createComment($data);
            return [
                'success' => true,
                'message' => 'Bình luận của bạn đã được gửi và đang chờ duyệt',
                'comment' => $comment
            ];
        } catch (\Exception $e) {
            return [
                'success' => false,
                'message' => 'Có lỗi xảy ra khi gửi bình luận'
            ];
        }
    }
    /**
     * Validate comment data from request
     *
     * @param Request $request
     * @param string $type
     * @param int $itemId
     * @return array
     */
    public function validateAndCreateComment(Request $request, $type, $itemId)
    {
        $data = [
            'type' => $type,
            'item_id' => $itemId,
            'content' => $request->input('content_vn'), // Map content_vn to content
            'name' => $request->input('name'),
            'email' => $request->input('email'),
            'rating' => $type === 'product' ? $request->input('rating') : null, // Rating chỉ cho product
        ];
        return $this->createComment($data);
    }
}<?php
namespace App\Services;
use App\Repositories\Interfaces\MailConfigRepositoryInterface;
use Illuminate\Support\Facades\Cache;
use Illuminate\Support\Facades\Log;
class MailConfigService
{
    protected $mailConfigRepository;
    public function __construct(MailConfigRepositoryInterface $mailConfigRepository)
    {
        $this->mailConfigRepository = $mailConfigRepository;
    }
    /**
     * Get active mail configuration or fallback to .env
     *
     * @return array
     */
    public function getActiveMailConfig()
    {
        $activeConfig = $this->mailConfigRepository->getActiveConfig();
        if ($activeConfig) {
            return $activeConfig->toConfigArray();
        }
        // Fallback to .env config
        return [
            'driver' => config('mail.driver'),
            'host' => config('mail.host'),
            'port' => config('mail.port'),
            'username' => config('mail.username'),
            'password' => config('mail.password'),
            'encryption' => config('mail.encryption'),
            'from' => [
                'address' => config('mail.from.address'),
                'name' => config('mail.from.name'),
            ],
        ];
    }
    /**
     * Get all mail configurations
     *
     * @return \Illuminate\Database\Eloquent\Collection
     */
    public function getAllConfigs()
    {
        return $this->mailConfigRepository->getAllConfigs();
    }
    /**
     * Create new mail configuration
     *
     * @param array $data
     * @return \App\Models\MailConfig
     */
    public function createConfig(array $data)
    {
        return $this->mailConfigRepository->createConfig($data);
    }
    /**
     * Update mail configuration
     *
     * @param array $data
     * @param int $id
     * @return bool
     */
    public function updateConfig(array $data, $id)
    {
        return $this->mailConfigRepository->updateConfig($data, $id);
    }
    /**
     * Set active mail configuration
     *
     * @param int $id
     * @return bool
     */
    public function setActiveConfig($id)
    {
        return $this->mailConfigRepository->setActiveConfig($id);
    }
    /**
     * Delete mail configuration
     *
     * @param int $id
     * @return bool
     */
    public function deleteConfig($id)
    {
        return $this->mailConfigRepository->deleteConfig($id);
    }
    /**
     * Test mail configuration
     *
     * @param array $config
     * @return array
     */
    public function testConfig(array $config)
    {
        return $this->mailConfigRepository->testConfig($config);
    }
    /**
     * Get mail configuration by ID
     *
     * @param int $id
     * @return \App\Models\MailConfig|null
     */
    public function getConfigById($id)
    {
        return $this->mailConfigRepository->find($id);
    }
    /**
     * Create a custom mailer instance with DB config
     *
     * @return \Illuminate\Mail\Mailer
     */
    public function createMailer()
    {
        $config = $this->getActiveMailConfig();
        // For port 587 (STARTTLS), use false to not wrap connection in SSL initially
        // Server will upgrade connection to TLS via STARTTLS command
        $transport = new \Symfony\Component\Mailer\Transport\Smtp\EsmtpTransport(
            $config['host'],
            $config['port'],
            false
        );
        $transport->setUsername($config['username']);
        $transport->setPassword($config['password']);
        // Set stream options for SSL/TLS connections
        $stream = $transport->getStream();
        if ($stream instanceof \Symfony\Component\Mailer\Transport\Smtp\Stream\SocketStream) {
            $stream->setStreamOptions([
                'ssl' => [
                    'verify_peer' => false,
                    'verify_peer_name' => false,
                    'allow_self_signed' => true
                ]
            ]);
        }
        $mailer = new \Illuminate\Mail\Mailer(
            'custom',
            app('view'),
            $transport,
            app('events')
        );
        $mailer->alwaysFrom($config['from']['address'], $config['from']['name']);
        return $mailer;
    }
}<?php
