namespace App\Services;
use App\Models\CateNew;
use App\Models\CateProduct;
use App\Models\News;
use App\Models\Product;
use App\Repositories\Interfaces\CommentRepositoryInterface;
use App\Repositories\Interfaces\NewsRepositoryInterface;
class NewsService
{
    protected $newsRepository;
    protected $commentRepository;
    public function __construct(NewsRepositoryInterface $newsRepository, CommentRepositoryInterface $commentRepository)
    {
        $this->newsRepository = $newsRepository;
        $this->commentRepository = $commentRepository;
    }
    /**
     * Get data for news category page
     *
     * @param int $id_cate_new
     * @return array
     */
    public function getCategoryNewsData($id_cate_new)
    {
        $data = [];
        // Cache category detail
        $data['category_detail'] = CateNew::where('status', 1)
            ->where('id_cate_new', $id_cate_new)
            ->select('id_cate_new', 'name_vn', 'name_en', 'slug_vn', 'slug_en', 'status')
            ->firstOrFail();
        $perPage = (int) \App\Models\NewsSetting::get('news_pagination', 8);
        // Cache news in category
        $data['news'] = News::where('category_id', $data['category_detail']->id_cate_new)
            ->where('status', 1)
            ->select('id_new', 'name_vn', 'name_en', 'intro_vn', 'intro_en', 'slug_vn', 'slug_en', 'image_vn', 'image_en', 'created_at', 'category_id')
            ->orderBy('created_at', 'desc')
            ->paginate($perPage);
        // Get common data
        $data = array_merge($data, $this->getCommonFrontendData());
        return $data;
    }
    /**
     * Get data for news detail page
     *
     * @param int $id_news
     * @return array
     */
    public function getDetailNewsData($id_news)
    {
        $data = [];
        // Cache news detail with category relationship
        $data['news_detail'] = News::with(['cate' => function ($query) {
            $query->select('id_cate_new', 'name_vn', 'name_en', 'slug_vn', 'slug_en');
        }])
            ->where('id_new', $id_news)
            ->select('id_new', 'name_vn', 'name_en', 'slug_vn', 'slug_en', 'image_vn', 'image_en', 'content_vn', 'content_en', 'created_at', 'category_id', 'keyword_vn', 'keyword_en', 'description_vn', 'description_en')
            ->firstOrFail();
        // Cache related news
        $data['related_news'] = News::where('category_id', $data['news_detail']->category_id)
            ->where('status', 1)
            ->where('id_new', '!=', $data['news_detail']->id_new)
            ->select('id_new', 'name_vn', 'name_en', 'slug_vn', 'slug_en', 'image_vn', 'image_en', 'created_at')
            ->orderBy('created_at', 'desc')
            ->limit(4)
            ->get();
        // Cache approved comments
        $data['comments'] = $this->commentRepository->getApprovedCommentsForItem('news', $data['news_detail']->id_new);
        // Get common data
        $data = array_merge($data, $this->getCommonFrontendData());
        return $data;
    }
    /**
     * Get common data used across frontend pages
     *
     * @return array
     */
    private function getCommonFrontendData()
    {
        return [
            'category_product' => CateProduct::where('status', 1)
                ->where('parent_id', 0)
                ->select('name_vn', 'name_en', 'status', 'slug_vn', 'slug_en')
                ->orderBy('created_at', 'desc')
                ->limit(8)
                ->get(),
            'product_hot' => Product::where('status', 1)
                ->where('hot', 1)
                ->select('name_vn', 'name_en', 'slug_vn', 'slug_en', 'image_vn', 'image_en', 'price', 'created_at')
                ->orderBy('created_at', 'desc')
                ->limit(5)
                ->get()
        ];
    }
}<?php
namespace App\Services;
use Illuminate\Support\Facades\RateLimiter;
class RateLimitService
{
    private int $maxAttempts;
    private int $decayMinutes;
    private string $prefix;
    public function __construct(string $prefix, int $maxAttempts = 5, int $decayMinutes = 15)
    {
        $this->prefix = $prefix;
        $this->maxAttempts = $maxAttempts;
        $this->decayMinutes = $decayMinutes;
    }
    /**
     * Lấy cache key cho rate limit
     */
    private function getRateLimitKey(string $key): string
    {
        return "{$this->prefix}_{$key}";
    }
    /**
     * Check if key is rate limited
     */
    public function isBlocked(string $key): bool
    {
        return RateLimiter::tooManyAttempts($this->getRateLimitKey($key), $this->maxAttempts);
    }
    /**
     * Increment attempts for key
     */
    public function incrementAttempts(string $key): void
    {
        RateLimiter::hit($this->getRateLimitKey($key), $this->decayMinutes * 60);
    }
    /**
     * Clear attempts on success
     */
    public function clearAttempts(string $key): void
    {
        RateLimiter::clear($this->getRateLimitKey($key));
    }
    /**
     * Get current attempts count
     */
    public function getAttempts(string $key): int
    {
        return RateLimiter::attempts($this->getRateLimitKey($key));
    }
    /**
     * Get rate limit error message
     */
    public function getErrorMessage(string $key = ''): string
    {
        $seconds = 0;
        if (!empty($key)) {
            $seconds = RateLimiter::availableIn($this->getRateLimitKey($key));
        }
        $minutes = ceil($seconds / 60);
        $minutes = $minutes > 0 ? $minutes : $this->decayMinutes;
        if ($this->prefix === 'contact') {
            return "Bạn đã gửi quá nhiều yêu cầu liên hệ. Vui lòng thử lại sau {$minutes} phút.";
        }
        return "Bạn đã nhập sai quá {$this->maxAttempts} lần. Vui lòng thử lại sau {$minutes} phút.";
    }
    /**
     * Get remaining attempts
     */
    public function getRemainingAttempts(string $key): int
    {
        return RateLimiter::remaining($this->getRateLimitKey($key), $this->maxAttempts);
    }
    /**
     * Get remaining time for blocked key in seconds
     */
    public function getRemainingTime(string $key): int
    {
        return RateLimiter::availableIn($this->getRateLimitKey($key));
    }
    /**
     * Factory method for login rate limiting
     */
    public static function forLogin(int $maxAttempts = 5, int $decayMinutes = 15): self
    {
        return new self('login', $maxAttempts, $decayMinutes);
    }
    /**
     * Factory method for contact form rate limiting
     */
    public static function forContact(int $maxAttempts = 3, int $decayMinutes = 5): self
    {
        return new self('contact', $maxAttempts, $decayMinutes);
    }
    /**
     * Factory method for cart operations rate limiting
     */
    public static function forCart(int $maxAttempts = 10, int $decayMinutes = 1): self
    {
        return new self('cart', $maxAttempts, $decayMinutes);
    }
    /**
     * Factory method for checkout operations rate limiting
     */
    public static function forCheckout(int $maxAttempts = 3, int $decayMinutes = 10): self
    {
        return new self('checkout', $maxAttempts, $decayMinutes);
    }
    /**
     * Factory method for content access rate limiting
     */
    public static function forContent(int $maxAttempts = 100, int $decayMinutes = 1): self
    {
        return new self('content', $maxAttempts, $decayMinutes);
    }
}<?php
namespace App\Services;
use App\Models\Product;
use Illuminate\Http\Request;
class SearchService
{
    /**
     * Search products based on query
     *
     * @param Request $request
     * @return array
     */
    public function searchProducts(Request $request)
    {
        $query = $request->get('q', '');
        $perPage = $this->getPerPageValue($request);
        $data = [];
        if (!empty($query)) {
            // Base query for search
            $searchQuery = Product::with(['cate:id_cate_product,name_vn,name_en,slug_vn,slug_en'])
                ->select('id_product', 'uuid', 'name_vn', 'name_en', 'slug_vn', 'slug_en', 'price', 'price_old', 'image_vn', 'image_en', 'intro_vn', 'intro_en', 'category_id', 'status', 'stt', 'created_at')
                ->where('status', 1);
            // Apply search filters
            $searchQuery = $this->applySearchFilters($searchQuery, $query);
            // Apply sorting (default by relevance, then by stt)
            $searchQuery = $this->applySearchSorting($searchQuery, $request);
            $data['products'] = $searchQuery->paginate($perPage)->appends($request->query());
        } else {
            $data['products'] = collect([]);
        }
        $data['search_query'] = $query;
        $data['total_results'] = $data['products']->total() ?? 0;
        return $data;
    }
    /**
     * Apply search filters to product query
     *
     * @param \Illuminate\Database\Eloquent\Builder $query
     * @param string $searchQuery
     * @return \Illuminate\Database\Eloquent\Builder
     */
    private function applySearchFilters($query, string $searchQuery)
    {
        // Search in product name
        $query->where(function ($q) use ($searchQuery) {
            $q->where('name_vn', 'like', "%{$searchQuery}%")
              ->orWhere('name_en', 'like', "%{$searchQuery}%");
        });
        return $query;
    }
    /**
     * Apply sorting to search results
     *
     * @param \Illuminate\Database\Eloquent\Builder $query
     * @param Request $request
     * @return \Illuminate\Database\Eloquent\Builder
     */
    private function applySearchSorting($query, Request $request)
    {
        $sort = $request->get('sort', 'relevance');
        switch ($sort) {
            case 'name_asc':
                $query->orderBy('name_vn', 'asc');
                break;
            case 'name_desc':
                $query->orderBy('name_vn', 'desc');
                break;
            case 'price_asc':
                $query->orderBy('price', 'asc');
                break;
            case 'price_desc':
                $query->orderBy('price', 'desc');
                break;
            case 'date_asc':
                $query->orderBy('created_at', 'asc');
                break;
            case 'date_desc':
                $query->orderBy('created_at', 'desc');
                break;
            case 'relevance':
            default:
                // For relevance, order by status (active first), then by stt, then by created date
                $query->orderBy('status', 'desc')
                      ->orderBy('stt', 'asc')
                      ->orderBy('created_at', 'desc');
                break;
        }
        return $query;
    }
    /**
     * Get per-page value with validation
     *
     * @param Request $request
     * @return int
     */
    private function getPerPageValue(Request $request)
    {
        $perPage = (int) $request->get('per_page', 16);
        if ($perPage <= 0 || $perPage > 100) {
            $perPage = 16;
        }
        return $perPage;
    }
    /**
     * Handle complete search request
     *
     * @param Request $request
     * @return array
     */
    public function handleSearchRequest(Request $request)
    {
        // Validate search query
        $request->validate([
            'q' => 'nullable|string|max:255',
            'sort' => 'nullable|string|in:relevance,name_asc,name_desc,price_asc,price_desc,date_asc,date_desc',
            'per_page' => 'nullable|integer|min:1|max:100'
        ]);
        $searchQuery = $request->get('q', '');
        // If no search query, return empty result
        if (empty(trim($searchQuery))) {
            return [
                'should_redirect' => true,
                'redirect_route' => 'web.home'
            ];
        }
        // Get search results
        $data = $this->searchProducts($request);
        // Add page metadata
        $data['page_title'] = 'Tìm kiếm: "' . $searchQuery . '"';
        $data['page_description'] = 'Kết quả tìm kiếm cho "' . $searchQuery . '" - ' . ($data['total_results'] ?? 0) . ' sản phẩm';
        return $data;
    }
    /**
     * Get search suggestions for AJAX
     *
     * @param Request $request
     * @return array
     */
    public function getSearchSuggestionsForAjax(Request $request)
    {
        $query = $request->get('q', '');
        if (strlen($query) < 2) {
            return ['suggestions' => []];
        }
        // Cache search suggestions
        $suggestions = Product::where('status', 1)
            ->where(function ($q) use ($query) {
                $q->where('name_vn', 'like', "%{$query}%")
                  ->orWhere('name_en', 'like', "%{$query}%");
            })
            ->orderBy('stt', 'asc')
            ->limit(10)
            ->pluck('name_vn')
            ->toArray();
        return ['suggestions' => $suggestions];
    }
}<?php
namespace App\Services;
use App\Repositories\Interfaces\SiteSettingRepositoryInterface;
class SiteSettingService
{
    protected $siteSettingRepository;
    public function __construct(SiteSettingRepositoryInterface $siteSettingRepository)
    {
        $this->siteSettingRepository = $siteSettingRepository;
    }
    /**
     * Get setting value by key
     *
     * @param string $key
     * @param mixed $default
     * @return mixed
     */
    public function getValue($key, $default = null)
    {
        $setting = $this->siteSettingRepository->getByKey($key);
        return $setting ? $setting->value : $default;
    }
    /**
     * Get settings by group
     *
     * @param string $group
     * @return \Illuminate\Database\Eloquent\Collection
     */
    public function getByGroup($group)
    {
        return $this->siteSettingRepository->getByGroup($group);
    }
    /**
     * Update or create setting
     *
     * @param string $key
     * @param mixed $value
     * @param string $type
     * @param string|null $group
     * @param string|null $description
     * @return \App\Models\SiteSetting
     */
    public function setSetting($key, $value, $type = 'text', $group = null, $description = null)
    {
        return $this->siteSettingRepository->updateOrCreate(
            ['key' => $key],
            [
                'value' => $value,
                'type' => $type,
                'group' => $group,
                'description' => $description,
            ]
        );
    }
    /**
     * Get homepage settings
     *
     * @return array
     */
    public function getHomepageSettings()
    {
        $settings = $this->getByGroup('homepage');
        $data = [];
        foreach ($settings as $setting) {
            // Nếu là JSON, decode ra array
            if ($setting->type == 'json' && is_string($setting->value)) {
                $data[$setting->key] = json_decode($setting->value, true);
            } else {
                $data[$setting->key] = $setting->value;
            }
        }
        return $data;
    }
}<?php
