namespace App\Models;
use GeneaLabs\LaravelModelCaching\Traits\Cachable;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Str;
class ProductSetting extends Model
{
    use Cachable, HasFactory;
    protected $fillable = [
        'uuid',
        'key',
        'value',
        'type',
        'group',
        'description',
        'is_active',
        'currency_unit',
        'sort_order',
    ];
    protected $casts = [
        'is_active' => 'boolean',
        'sort_order' => 'integer',
    ];
    /**
     * Boot the model.
     */
    protected static function boot()
    {
        parent::boot();
        static::creating(function ($model) {
            if (empty($model->uuid)) {
                $model->uuid = (string) Str::uuid();
            }
        });
    }
    /**
     * Get the route key for the model.
     */
    public function getRouteKeyName()
    {
        return 'uuid';
    }
    /**
     * Lấy giá trị setting theo key
     */
    public static function get($key, $default = null)
    {
        $setting = static::where('key', $key)->where('is_active', true)->first();
        if (! $setting) {
            return $default;
        }
        return static::castValue($setting->value, $setting->type);
    }
    /**
     * Get system-wide currency unit.
     */
    public static function getCurrencyUnit(): string
    {
        try {
            $val = static::get('products_currency_unit');
            if (! empty($val)) {
                return (string) $val;
            }
            // Fallback to column if exists
            $row = static::whereNotNull('currency_unit')->first();
            return $row && ! empty($row->currency_unit) ? (string) $row->currency_unit : 'đ';
        } catch (\Throwable $e) {
            return 'đ';
        }
    }
    /**
     * Cập nhật hoặc tạo mới setting
     */
    public static function set($key, $value, $type = 'text', $group = 'general', $description = null)
    {
        return static::updateOrCreate(
            ['key' => $key],
            [
                'value' => $value,
                'type' => $type,
                'group' => $group,
                'description' => $description,
                'is_active' => true,
            ]
        );
    }
    /**
     * Chuyển đổi giá trị theo type
     */
    protected static function castValue($value, $type)
    {
        switch ($type) {
            case 'number':
                return (int) $value;
            case 'json':
                return json_decode($value, true);
            case 'boolean':
                return (bool) $value;
            default:
                return $value;
        }
    }
    /**
     * Scope theo group
     */
    public function scopeByGroup($query, $group)
    {
        return $query->where('group', $group);
    }
    /**
     * Scope chỉ active
     */
    public function scopeActive($query)
    {
        return $query->where('is_active', true);
    }
}<?php
namespace App\Models;
use App\Traits\BaseLogsActivity;
use GeneaLabs\LaravelModelCaching\Traits\Cachable;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsToMany;
class Role extends Model
{
    use BaseLogsActivity, Cachable, HasFactory;
    protected $table = 'tp_roles';
    protected $fillable = [
        'name',
        'display_name',
        'description'
    ];
    /**
     * Relationship với Permission
     */
    public function permissions(): BelongsToMany
    {
        return $this->belongsToMany(Permission::class, 'tp_role_permission', 'role_id', 'permission_id');
    }
    /**
     * Relationship với User
     */
    public function users(): BelongsToMany
    {
        return $this->belongsToMany(User::class, 'tp_role_user', 'role_id', 'user_id');
    }
    /**
     * Gán permissions cho role
     */
    public function givePermissionTo($permissions): void
    {
        $permissions = $this->getPermissionIds($permissions);
        $this->permissions()->syncWithoutDetaching($permissions);
        $this->forgetCachedPermissions();
    }
    /**
     * Thu hồi permissions
     */
    public function revokePermissionTo($permissions): void
    {
        $permissions = $this->getPermissionIds($permissions);
        $this->permissions()->detach($permissions);
        $this->forgetCachedPermissions();
    }
    /**
     * Đồng bộ permissions
     */
    public function syncPermissions($permissions): void
    {
        $permissions = $this->getPermissionIds($permissions);
        $this->permissions()->sync($permissions);
        $this->forgetCachedPermissions();
    }
    /**
     * Kiểm tra role có permission không
     */
    public function hasPermission($permissionName): bool
    {
        if (is_string($permissionName)) {
            return $this->permissions()->where('name', $permissionName)->exists();
        }
        if (is_array($permissionName)) {
            return $this->permissions()->whereIn('name', $permissionName)->exists();
        }
        return false;
    }
    /**
     * Chuyển đổi permissions thành array IDs
     */
    private function getPermissionIds($permissions): array
    {
        if (is_numeric($permissions)) {
            return [$permissions];
        }
        if (is_array($permissions)) {
            return $permissions;
        }
        if (is_string($permissions)) {
            $permission = Permission::where('name', $permissions)->first();
            return $permission ? [$permission->id] : [];
        }
        return [];
    }
    /**
     * Xóa cache permissions
     */
    private function forgetCachedPermissions(): void
    {
        // No cache to clear with Cachable
    }
}<?php
