namespace App\Services;
use App\Repositories\Interfaces\ActivityLogRepositoryInterface;
use Illuminate\Pagination\LengthAwarePaginator;
use Spatie\Activitylog\Models\Activity;
class ActivityLogService
{
    /**
     * @var ActivityLogRepositoryInterface
     */
    protected $activityLogRepository;
    /**
     * Common attribute translations for human-readable diff.
     *
     * @var array
     */
    protected static $attributeLabels = [
        'name_vn' => 'Tên (Tiếng Việt)',
        'name_en' => 'Tên (English)',
        'slug_vn' => 'Đường dẫn (VN)',
        'slug_en' => 'Đường dẫn (EN)',
        'intro_vn' => 'Mô tả ngắn (VN)',
        'intro_en' => 'Mô tả ngắn (EN)',
        'content_vn' => 'Nội dung (VN)',
        'content_en' => 'Nội dung (EN)',
        'keyword_vn' => 'Từ khóa SEO (VN)',
        'keyword_en' => 'Từ khóa SEO (EN)',
        'price' => 'Giá bán',
        'price_old' => 'Giá cũ',
        'status' => 'Trạng thái',
        'is_featured' => 'Nổi bật',
        'is_hot' => 'Bán chạy',
        'category_id' => 'Danh mục',
        'parent_id' => 'Danh mục cha',
        'image_vn' => 'Hình ảnh đại diện',
        'image_en' => 'Hình ảnh (EN)',
        'image_detail' => 'Thư viện ảnh',
        'sort' => 'Thứ tự hiển thị',
        'fullname' => 'Họ và tên',
        'username' => 'Tên đăng nhập',
        'email' => 'Địa chỉ Email',
        'phone' => 'Số điện thoại',
        'address' => 'Địa chỉ',
        'level' => 'Phân quyền',
        'avatar' => 'Ảnh đại diện',
        'total' => 'Tổng tiền',
        'payment_method' => 'Phương thức thanh toán',
        'display_name' => 'Tên hiển thị',
        'description' => 'Mô tả',
    ];
    /**
     * ActivityLogService constructor.
     *
     * @param ActivityLogRepositoryInterface $activityLogRepository
     */
    public function __construct(ActivityLogRepositoryInterface $activityLogRepository)
    {
        $this->activityLogRepository = $activityLogRepository;
    }
    /**
     * Get paginated and filtered activity logs.
     *
     * @param array $filters
     * @param int $perPage
     * @return LengthAwarePaginator
     */
    public function getLogs(array $filters = [], int $perPage = 20): LengthAwarePaginator
    {
        return $this->activityLogRepository->getFilteredLogs($filters, $perPage);
    }
    /**
     * Get distinct log module names for filtering.
     *
     * @return array
     */
    public function getLogNames(): array
    {
        return $this->activityLogRepository->getDistinctLogNames();
    }
    /**
     * Get single log with formatted diff data.
     *
     * @param int $id
     * @return array|null
     */
    public function getLogDetail(int $id): ?array
    {
        $log = $this->activityLogRepository->findById($id);
        if (!$log) {
            return null;
        }
        $formattedDiff = $this->formatDiff($log);
        return [
            'log' => $log,
            'event_label' => $this->getEventBadge($log->event),
            'diff' => $formattedDiff,
        ];
    }
    /**
     * Format before/after diff for display.
     *
     * @param Activity $log
     * @return array
     */
    public function formatDiff(Activity $log): array
    {
        $properties = $log->properties ? $log->properties->toArray() : [];
        $attributes = $properties['attributes'] ?? [];
        $old = $properties['old'] ?? [];
        $diff = [];
        $allKeys = array_unique(array_merge(array_keys($old), array_keys($attributes)));
        foreach ($allKeys as $key) {
            if (in_array($key, ['created_at', 'updated_at', 'password', 'remember_token'])) {
                continue;
            }
            $oldVal = $old[$key] ?? null;
            $newVal = $attributes[$key] ?? null;
            // Only include if value actually changed or it's a create/delete event
            if ($log->event === 'updated' && $oldVal === $newVal) {
                continue;
            }
            $diff[] = [
                'field' => $key,
                'label' => self::$attributeLabels[$key] ?? ucfirst(str_replace('_', ' ', $key)),
                'old' => is_array($oldVal) ? json_encode($oldVal, JSON_UNESCAPED_UNICODE) : $oldVal,
                'new' => is_array($newVal) ? json_encode($newVal, JSON_UNESCAPED_UNICODE) : $newVal,
            ];
        }
        return $diff;
    }
    /**
     * Get human-readable badge data for an event.
     *
     * @param string|null $event
     * @return array
     */
    public function getEventBadge(?string $event): array
    {
        return match ($event) {
            'created' => ['label' => 'Thêm mới', 'class' => 'bg-emerald-50 text-emerald-700 border-emerald-200'],
            'updated' => ['label' => 'Cập nhật', 'class' => 'bg-amber-50 text-amber-700 border-amber-200'],
            'deleted' => ['label' => 'Xóa', 'class' => 'bg-rose-50 text-rose-700 border-rose-200'],
            default => ['label' => ucfirst($event ?? 'Khác'), 'class' => 'bg-slate-50 text-slate-700 border-slate-200'],
        };
    }
    /**
     * Clean activity logs older than specified days.
     *
     * @param int $days
     * @return int
     */
    public function cleanLogs(int $days = 60): int
    {
        return $this->activityLogRepository->cleanOldLogs($days);
    }
    /**
     * Delete a single activity log.
     *
     * @param int $id
     * @return bool
     */
    public function deleteLog(int $id): bool
    {
        return $this->activityLogRepository->deleteLog($id);
    }
}<?php
namespace App\Services;
use App\Models\Analytic;
use App\Models\Product;
use App\Repositories\Interfaces\DashboardRepositoryInterface;
use Carbon\Carbon;
use Illuminate\Support\Facades\Cache;
use Illuminate\Support\Facades\DB;
class DashboardService
{
    /**
     * @var DashboardRepositoryInterface
     */
    protected $dashboardRepository;
    /**
     * Cache TTL in seconds (5 minutes).
     */
    const CACHE_TTL = 300;
    /**
     * DashboardService constructor.
     *
     * @param DashboardRepositoryInterface $dashboardRepository
     */
    public function __construct(DashboardRepositoryInterface $dashboardRepository)
    {
        $this->dashboardRepository = $dashboardRepository;
    }
    /**
     * Get complete dashboard overview dataset.
     *
     * @param bool $refresh
     * @return array
     */
    public function getOverviewData(bool $refresh = false): array
    {
        $cacheKey = 'admin:dashboard:overview';
        if ($refresh) {
            Cache::forget($cacheKey);
        }
        return Cache::remember($cacheKey, self::CACHE_TTL, function () {
            $summary = $this->dashboardRepository->getRevenueAndOrderSummary();
            $lowStock = $this->dashboardRepository->getLowStockProducts(5, 10);
            $overdueOrders = $this->dashboardRepository->getOverduePendingOrders(24, 10);
            $topProducts = $this->dashboardRepository->getTopSellingProducts(5);
            $recentOrders = $this->dashboardRepository->getRecentOrders(6);
            // General counts
            $totalProducts = Product::count();
            $totalNews = DB::table('tp_news')->count();
            $totalComments = DB::table('tp_comments')->count();
            // Web visit metrics
            $totalViews = (int) Analytic::sum('visit_count');
            $now = Carbon::now();
            $monthViews = (int) Analytic::whereMonth('visit_date', $now->month)
                ->whereYear('visit_date', $now->year)
                ->sum('visit_count');
            $lastMonth = $now->copy()->subMonth();
            $lastMonthViews = (int) Analytic::whereMonth('visit_date', $lastMonth->month)
                ->whereYear('visit_date', $lastMonth->year)
                ->sum('visit_count');
            $weekStart = $now->copy()->startOfWeek();
            $weekEnd = $now->copy()->endOfWeek();
            $weekViews = (int) Analytic::whereBetween('visit_date', [$weekStart, $weekEnd])
                ->sum('visit_count');
            return [
                'summary' => $summary,
                'low_stock' => $lowStock,
                'low_stock_count' => count($lowStock),
                'overdue_orders' => $overdueOrders,
                'overdue_orders_count' => count($overdueOrders),
                'top_products' => $topProducts,
                'recent_orders' => $recentOrders,
                'total_products' => $totalProducts,
                'total_news' => $totalNews,
                'total_comments' => $totalComments,
                'total_views' => $totalViews,
                'month_views' => $monthViews,
                'last_month_views' => $lastMonthViews,
                'week_views' => $weekViews,
            ];
        });
    }
    /**
     * Get revenue chart data formatted for ApexCharts.
     *
     * @param string $period ('7_days', '30_days', 'year')
     * @param int|null $year
     * @return array
     */
    public function getRevenueChartData(string $period = '30_days', ?int $year = null): array
    {
        $targetYear = $year ?: (int) date('Y');
        $cacheKey = "admin:dashboard:chart:{$period}:{$targetYear}";
        return Cache::remember($cacheKey, self::CACHE_TTL, function () use ($period, $targetYear) {
            if ($period === '7_days') {
                $data = $this->dashboardRepository->getDailyRevenueChart(7);
            } elseif ($period === 'year') {
                $data = $this->dashboardRepository->getMonthlyRevenueChart($targetYear);
            } else {
                $data = $this->dashboardRepository->getDailyRevenueChart(30);
            }
            return $data;
        });
    }
    /**
     * Flush dashboard cache.
     *
     * @param int|null $year
     * @return void
     */
    public function flushCache(?int $year = null): void
    {
        Cache::forget('admin:dashboard:overview');
        $currentYear = (int) date('Y');
        $years = array_unique([$currentYear, $currentYear - 1, $currentYear - 2, $year ?? $currentYear]);
        foreach ($years as $y) {
            Cache::forget("admin:dashboard:chart:7_days:{$y}");
            Cache::forget("admin:dashboard:chart:30_days:{$y}");
            Cache::forget("admin:dashboard:chart:year:{$y}");
        }
    }
}<?php
namespace App\Services;
use Exception;
use Illuminate\Support\Facades\File;
use Illuminate\Support\Facades\Http;
use Illuminate\Support\Facades\Log;
use Illuminate\Support\Str;
class DemoImageDownloaderService
{
    protected ImageService $imageService;
    public function __construct(ImageService $imageService)
    {
        $this->imageService = $imageService;
    }
    /**
     * Xóa sạch toàn bộ file/folder nằm trong public/uploads/demo/
     */
    public function cleanOldUploads(): bool
    {
        $demoPath = public_path('uploads/demo');
        if (File::exists($demoPath)) {
            File::cleanDirectory($demoPath);
        } else {
            File::makeDirectory($demoPath, 0755, true);
        }
        return true;
    }
    /**
     * Tải ảnh từ LoremFlickr / Picsum Photos, lưu tạm vào storage, convert sang WebP và lưu vào public/uploads/demo/
     *
     * @param  string  $keyword  Từ khóa tìm kiếm ảnh
     * @param  int  $width  Chiều rộng
     * @param  int  $height  Chiều cao
     * @return string|null Đường dẫn tương đối của file webp (vd: uploads/demo/xxx.webp) hoặc null nếu thất bại
     */
    public function fetchAndSaveImage(string $keyword, int $width = 800, int $height = 600): ?string
    {
        $tempDir = storage_path('app/temp');
        if (! File::exists($tempDir)) {
            File::makeDirectory($tempDir, 0755, true);
        }
        $tempFileName = 'demo_' . Str::slug($keyword) . '_' . uniqid() . '.jpg';
        $tempFilePath = $tempDir . DIRECTORY_SEPARATOR . $tempFileName;
        $targetDir = public_path('uploads/demo');
        if (! File::exists($targetDir)) {
            File::makeDirectory($targetDir, 0755, true);
        }
        $slugKeyword = Str::slug($keyword);
        $finalName = ($slugKeyword ?: 'image') . '_' . uniqid() . '.webp';
        $targetPath = $targetDir . DIRECTORY_SEPARATOR . $finalName;
        try {
            $encodedKeyword = urlencode($keyword);
            // Danh sách các nguồn tải ảnh demo theo thứ tự ưu tiên
            $sources = [
                "https://loremflickr.com/{$width}/{$height}/{$encodedKeyword}",
                "https://picsum.photos/{$width}/{$height}",
            ];
            $imageBytes = null;
            foreach ($sources as $url) {
                try {
                    $response = Http::withHeaders([
                        'User-Agent' => 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                    ])->withOptions([
                        'verify' => false,
                        'allow_redirects' => true,
                    ])->timeout(15)->get($url);
                    if ($response->successful() && strlen($response->body()) > 0) {
                        $imageBytes = $response->body();
                        break;
                    }
                } catch (Exception $subEx) {
                    Log::warning("Thử tải ảnh từ {$url} thất bại: " . $subEx->getMessage());
                    continue;
                }
            }
            if (! $imageBytes) {
                Log::warning("Không thể tải ảnh demo cho từ khóa [{$keyword}] từ bất kỳ nguồn nào.");
                return null;
            }
            // Lưu nội dung tải về vào file tạm
            File::put($tempFilePath, $imageBytes);
            if (! File::exists($tempFilePath) || filesize($tempFilePath) === 0) {
                Log::warning("File ảnh tạm không hợp lệ: {$tempFilePath}");
                return null;
            }
            // Gọi ImageService để convert sang WebP
            $savedFileName = $this->imageService->convertToWebp($tempFilePath, $targetPath, 80);
            if (! $savedFileName) {
                Log::warning("Không thể chuyển đổi WebP cho ảnh demo: {$tempFilePath}");
                return null;
            }
            return "uploads/demo/{$savedFileName}";
        } catch (Exception $e) {
            Log::error("Lỗi khi tải hoặc convert ảnh demo: " . $e->getMessage());
            return null;
        } finally {
            // Xóa file tạm
            if (File::exists($tempFilePath)) {
                File::delete($tempFilePath);
            }
        }
    }
}<?php
namespace App\Services;
use App\Models\Media;
use App\Repositories\Interfaces\MediaRepositoryInterface;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\File;
use Illuminate\Support\Facades\Log;
use Illuminate\Support\Str;
use Intervention\Image\Facades\Image;
class MediaService
{
    /**
     * @var MediaRepositoryInterface
     */
    protected $mediaRepo;
    /**
     * Allowed extensions.
     */
    protected $imageExtensions = ['jpg', 'jpeg', 'png', 'gif', 'webp'];
    protected $videoExtensions = ['mp4', 'webm', 'mov', 'ogg'];
    protected $docExtensions = ['pdf', 'doc', 'docx', 'xls', 'xlsx', 'svg', 'ico'];
    public function __construct(MediaRepositoryInterface $mediaRepo)
    {
        $this->mediaRepo = $mediaRepo;
    }
    /**
     * Get paginated media items.
     */
    public function paginate(array $filters = [], int $perPage = 24)
    {
        return $this->mediaRepo->paginateWithFilters($filters, $perPage);
    }
    /**
     * Upload and process a single file.
     *
     * @param UploadedFile $file
     * @param string $module
     * @param int|null $userId
     * @return Media|null
     */
    public function upload(UploadedFile $file, string $module = 'general', ?int $userId = null): ?Media
    {
        @ini_set('memory_limit', '1024M');
        $originalName = $file->getClientOriginalName();
        $rawExtension = strtolower($file->getClientOriginalExtension());
        $cleanModule = Str::slug($module ?: 'general');
        $year = date('Y');
        $month = date('m');
        // Path structure: uploads/{module}/{Y}/{m}/
        $subFolder = "uploads/{$cleanModule}/{$year}/{$month}";
        $targetDirectory = public_path($subFolder);
        if (!File::exists($targetDirectory)) {
            File::makeDirectory($targetDirectory, 0755, true);
        }
        $baseName = Str::slug(pathinfo($originalName, PATHINFO_FILENAME));
        if (empty($baseName)) {
            $baseName = 'media_' . time();
        }
        $uniqueSuffix = time() . '_' . Str::random(4);
        $dimensions = null;
        $isImage = in_array($rawExtension, $this->imageExtensions);
        try {
            if ($isImage) {
                // Auto WebP conversion with max 1920px dimensions
                $targetFileName = "{$baseName}_{$uniqueSuffix}.webp";
                $fullFilePath = "{$targetDirectory}/{$targetFileName}";
                $img = Image::make($file);
                // Resize if exceeding 1920x1920
                if ($img->width() > 1920 || $img->height() > 1920) {
                    $img->resize(1920, 1920, function ($constraint) {
                        $constraint->aspectRatio();
                        $constraint->upsize();
                    });
                }
                $dimensions = "{$img->width()}x{$img->height()}";
                $img->encode('webp', 80)->save($fullFilePath);
                $img->destroy();
                $storedSize = File::size($fullFilePath);
                $finalMime = 'image/webp';
                $finalExt = 'webp';
            } else {
                // Direct store for SVG, videos, documents
                $targetFileName = "{$baseName}_{$uniqueSuffix}.{$rawExtension}";
                $fullFilePath = "{$targetDirectory}/{$targetFileName}";
                $file->move($targetDirectory, $targetFileName);
                $storedSize = File::size($fullFilePath);
                $finalMime = File::mimeType($fullFilePath) ?: $file->getClientMimeType();
                $finalExt = $rawExtension;
            }
            $relativePath = "{$subFolder}/{$targetFileName}";
            return Media::create([
                'uuid' => (string) Str::uuid(),
                'name' => pathinfo($originalName, PATHINFO_FILENAME),
                'file_name' => $targetFileName,
                'path' => $relativePath,
                'module' => $cleanModule,
                'mime_type' => $finalMime,
                'extension' => $finalExt,
                'size' => $storedSize,
                'dimensions' => $dimensions,
                'created_by' => $userId,
            ]);
        } catch (\Throwable $e) {
            Log::error('MediaService upload error: ' . $e->getMessage());
            // Fallback: Store original file without modification
            try {
                $targetFileName = "{$baseName}_{$uniqueSuffix}.{$rawExtension}";
                $fullFilePath = "{$targetDirectory}/{$targetFileName}";
                $file->move($targetDirectory, $targetFileName);
                $relativePath = "{$subFolder}/{$targetFileName}";
                return Media::create([
                    'uuid' => (string) Str::uuid(),
                    'name' => pathinfo($originalName, PATHINFO_FILENAME),
                    'file_name' => $targetFileName,
                    'path' => $relativePath,
                    'module' => $cleanModule,
                    'mime_type' => $file->getClientMimeType() ?: 'application/octet-stream',
                    'extension' => $rawExtension,
                    'size' => File::size($fullFilePath),
                    'dimensions' => null,
                    'created_by' => $userId,
                ]);
            } catch (\Throwable $fallbackErr) {
                Log::error('MediaService fallback upload error: ' . $fallbackErr->getMessage());
                return null;
            }
        }
    }
    /**
     * Upload multiple files.
     */
    public function uploadMultiple(array $files, string $module = 'general', ?int $userId = null): array
    {
        $uploaded = [];
        foreach ($files as $file) {
            if ($file instanceof UploadedFile) {
                $item = $this->upload($file, $module, $userId);
                if ($item) {
                    $uploaded[] = $item;
                }
            }
        }
        return $uploaded;
    }
    /**
     * Delete media item.
     */
    public function delete(int $id): bool
    {
        $media = Media::find($id);
        if (!$media) {
            return false;
        }
        // Delete physical file
        $physicalPath = public_path($media->path);
        if (File::exists($physicalPath)) {
            File::delete($physicalPath);
        }
        return (bool) $media->delete();
    }
}<?php
namespace App\Services;
class ModelToggleService
{
    /**
     * Whitelist of toggleable attributes to prevent arbitrary column alteration
     */
    protected array $allowedToggleFields = [
        'status',
        'home',
        'hot',
        'sale',
        'active',
    ];
    public function toggleModelStatus($uuid, $status, $fieldName, $model)
    {
        // Enforce whitelist check
        if (!in_array($fieldName, $this->allowedToggleFields, true)) {
            return response()->json(['message' => 'Trường cập nhật không hợp lệ'], 403);
        }
        $sanitizedStatus = (int)(bool)$status;
        $updated = $model::where('uuid', $uuid)->update([$fieldName => $sanitizedStatus]);
        if ($updated) {
            $mess = $sanitizedStatus == 1 ? 'Kích hoạt' : 'Tắt';
            toast($mess.' thành công');
            return response()->json(['message' => $mess.' '.$fieldName.' thành công']);
        }
        toast('Không tìm thấy '.$fieldName, 'error');
        return response()->json(['message' => 'Không có bản ghi nào được cập nhật'], 400);
    }
    public function updateModelOrder($request, $uuid, $model)
    {
        $item = $model::where('uuid', $uuid)->first();
        if ($item) {
            $item->stt = max(0, (int) $request->input('stt', 1));
            $item->save();
            return response()->json(['success' => true]);
        }
        return response()->json(['success' => false]);
    }
}<?php
namespace App\Services;
use App\Models\CateProduct;
use App\Models\Product;
use App\Repositories\Interfaces\CommentRepositoryInterface;
use App\Repositories\Interfaces\ProductRepositoryInterface;
use Illuminate\Http\Request;
class ProductService
{
    protected $productRepository;
    protected $commentRepository;
    public function __construct(ProductRepositoryInterface $productRepository, CommentRepositoryInterface $commentRepository)
    {
        $this->productRepository = $productRepository;
        $this->commentRepository = $commentRepository;
    }
    /**
     * Get data for product category page
     *
     * @param int $id_cate_product
     * @param Request $request
     * @return array
     */
    public function getCategoryProductData($id_cate_product, Request $request)
    {
        $data = [];
        // Cache category data
        $data['category_detail'] = CateProduct::where('status', 1)->where('id_cate_product', $id_cate_product)->firstOrFail();
        // Cache category list (sidebar) - Load all categories with hierarchy
        $data['category_product'] = CateProduct::with(['products', 'children.products'])
            ->where('status', 1)
            ->orderBy('stt', 'asc')
            ->get()
            ->groupBy('parent_id');
        // Build category id list (include children recursively)
        $categoryIds = $this->getAllCategoryIds($data['category_detail']->id_cate_product);
        // Base query
        $query = Product::with(['cate:id_cate_product,name_vn,name_en,slug_vn,slug_en'])
            ->select('id_product', 'uuid', 'name_vn', 'name_en', 'slug_vn', 'slug_en', 'price', 'price_old', 'image_vn', 'image_en', 'intro_vn', 'intro_en', 'category_id', 'status', 'stt', 'created_at')
            ->whereIn('category_id', $categoryIds)
            ->where('status', 1)
            ->orderBy('created_at', 'desc');
        // Apply filters
        $query = $this->applyProductFilters($query, $request);
        // Apply sorting
        $query = $this->applyProductSorting($query, $request);
        // Get per-page value
        $perPage = $this->getPerPageValue($request);
        $data['products'] = $query->paginate($perPage)->appends($request->query());
        return $data;
    }
    /**
     * Get data for product detail page
     *
     * @param int $id_product
     * @return array
     */
    public function getDetailProductData($id_product)
    {
        $data = [];
        // Cache product detail
        $data['product_detail'] = Product::with(['cate:id_cate_product,name_vn,name_en,slug_vn,slug_en'])
            ->where('id_product', $id_product)
            ->firstOrFail();
        // Cache related products
        $data['related_product'] = Product::where('category_id', $data['product_detail']->category_id)
            ->where('id_product', '!=', $data['product_detail']->id_product)
            ->where('status', 1)
            ->orderBy('stt', 'asc')
            ->limit(8)
            ->get();
        // Cache approved comments
        $data['comments'] = $this->commentRepository->getApprovedCommentsForItem('product', $data['product_detail']->id_product);
        return $data;
    }
    /**
     * Apply filters to product query
     *
     * @param \Illuminate\Database\Eloquent\Builder $query
     * @param Request $request
     * @return \Illuminate\Database\Eloquent\Builder
     */
    private function applyProductFilters($query, Request $request)
    {
        // Name search filter
        if ($request->filled('name')) {
            $name = $request->get('name');
            $query->where(function ($q) use ($name) {
                $q->where('name_vn', 'like', "%{$name}%")
                  ->orWhere('name_en', 'like', "%{$name}%");
            });
        }
        // Price filters
        if ($request->filled('price_min')) {
            $priceMin = (float) $request->get('price_min');
            $query->where('price', '>=', $priceMin);
        }
        if ($request->filled('price_max')) {
            $priceMax = (float) $request->get('price_max');
            $query->where('price', '<=', $priceMax);
        }
        // Date filters
        if ($request->filled('date_from')) {
            $dateFrom = $request->get('date_from');
            $query->whereDate('created_at', '>=', $dateFrom);
        }
        if ($request->filled('date_to')) {
            $dateTo = $request->get('date_to');
            $query->whereDate('created_at', '<=', $dateTo);
        }
        return $query;
    }
    /**
     * Apply sorting to product query
     *
     * @param \Illuminate\Database\Eloquent\Builder $query
     * @param Request $request
     * @return \Illuminate\Database\Eloquent\Builder
     */
    private function applyProductSorting($query, Request $request)
    {
        $sort = $request->get('sort');
        switch ($sort) {
            case 'name_asc':
                $query->orderBy('name_vn', 'asc');
                break;
            case 'name_desc':
                $query->orderBy('name_vn', 'desc');
                break;
            case 'price_asc':
                $query->orderBy('price', 'asc');
                break;
            case 'price_desc':
                $query->orderBy('price', 'desc');
                break;
            case 'date_asc':
                $query->orderBy('created_at', 'asc');
                break;
            case 'date_desc':
                $query->orderBy('created_at', 'desc');
                break;
            default:
                $query->orderBy('stt', 'asc');
                break;
        }
        return $query;
    }
    /**
     * Get per-page value with validation
     *
     * @param Request $request
     * @return int
     */
    private function getPerPageValue(Request $request)
    {
        $defaultPerPage = (int) \App\Models\ProductSetting::get('products_pagination', 8);
        $perPage = (int) $request->get('per_page', $defaultPerPage);
        if ($perPage <= 0 || $perPage > 100) {
            $perPage = $defaultPerPage;
        }
        return $perPage;
    }
    /**
     * Get all category IDs recursively (parent + all children)
     *
     * @param int $parentId
     * @return array
     */
    private function getAllCategoryIds($parentId)
    {
        $categoryIds = [$parentId];
        $this->getChildCategoryIds($parentId, $categoryIds);
        return $categoryIds;
    }
    /**
     * Recursively get all child category IDs
     *
     * @param int $parentId
     * @param array &$categoryIds
     * @return void
     */
    private function getChildCategoryIds($parentId, &$categoryIds)
    {
        $children = CateProduct::where('parent_id', $parentId)->pluck('id_cate_product')->toArray();
        foreach ($children as $childId) {
            $categoryIds[] = $childId;
            $this->getChildCategoryIds($childId, $categoryIds);
        }
    }
    /**
     * Get data for brand product page
     *
     * @param int $id_brand
     * @param Request|null $request
     * @return array
     */
    public function getBrandProductData($id_brand, Request $request = null)
    {
        if (!$request) {
            $request = request();
        }
        $data = [];
        $data['brand_detail'] = \App\Models\Brand::where('status', 1)->where('id_brand', $id_brand)->firstOrFail();
        $data['category_detail'] = (object) [
            'id_cate_product' => 0,
            'name_vn' => $data['brand_detail']->name_vn,
            'name_en' => $data['brand_detail']->name_en ?? $data['brand_detail']->name_vn,
            'name' => $data['brand_detail']->name_vn,
            'slug' => $data['brand_detail']->slug ?? \Illuminate\Support\Str::slug($data['brand_detail']->name_vn),
            'intro_vn' => 'Xe / Sản phẩm thương hiệu ' . $data['brand_detail']->name_vn,
            'description_vn' => 'Danh sách xe thuộc thương hiệu ' . $data['brand_detail']->name_vn,
            'keyword_vn' => $data['brand_detail']->name_vn,
            'image' => $data['brand_detail']->image,
        ];
        $data['category_product'] = CateProduct::with(['products', 'children.products'])
            ->where('status', 1)
            ->orderBy('stt', 'asc')
            ->get()
            ->groupBy('parent_id');
        $query = Product::with(['cate:id_cate_product,name_vn,name_en,slug_vn,slug_en'])
            ->select('id_product', 'uuid', 'name_vn', 'name_en', 'slug_vn', 'slug_en', 'price', 'price_old', 'image_vn', 'image_en', 'intro_vn', 'intro_en', 'category_id', 'brand_id', 'status', 'stt', 'created_at')
            ->where('brand_id', $id_brand)
            ->where('status', 1)
            ->orderBy('created_at', 'desc');
        $query = $this->applyProductFilters($query, $request);
        $query = $this->applyProductSorting($query, $request);
        $perPage = $this->getPerPageValue($request);
        $data['products'] = $query->paginate($perPage)->appends($request->query());
        return $data;
    }
}<?php
