namespace App\Models;
use App\Traits\AutoImagePathsTrait;
use App\Traits\BaseLogsActivity;
use GeneaLabs\LaravelModelCaching\Traits\Cachable;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
class Product extends Model
{
    use AutoImagePathsTrait, BaseLogsActivity, Cachable, HasFactory;
    protected $table = 'tp_products';
    protected $primaryKey = 'id_product';
    protected $fillable = [
        'uuid',
        'name_vn',
        'name_en',
        'slug_vn',
        'slug_en',
        'intro_vn',
        'intro_en',
        'price',
        'price_old',
        'content_vn',
        'content_en',
        'image_vn',
        'image_en',
        'image_detail',
        'video',
        'stt',
        'keyword_vn',
        'keyword_en',
        'description_vn',
        'description_en',
        'category_id',
        'brand_id',
        'quantity',
        'status',
        'hot',
        'home',
        'sale',
    ];
    public function getSlugAttribute()
    {
        $locale = app()->getLocale();
        return $this->{'slug_' . $locale} ?: ($this->slug_vn ?: $this->slug_en);
    }
    public function getNameAttribute()
    {
        $locale = app()->getLocale();
        return $this->{'name_' . $locale} ?: ($this->name_vn ?: $this->name_en);
    }
    public function getImageAttribute()
    {
        $locale = app()->getLocale();
        return $this->{'image_' . $locale} ?: ($this->image_vn ?: $this->image_en);
    }
    public function getVideoUrlAttribute()
    {
        if (empty($this->video)) {
            return null;
        }
        if (filter_var($this->video, FILTER_VALIDATE_URL)) {
            return $this->video;
        }
        return asset($this->video);
    }
    public function getKeywordAttribute()
    {
        $locale = app()->getLocale();
        return $this->{'keyword_' . $locale} ?: ($this->keyword_vn ?: $this->keyword_en);
    }
    public function getKeywordsAttribute()
    {
        return $this->getKeywordAttribute();
    }
    public function getDescriptionAttribute()
    {
        $locale = app()->getLocale();
        return $this->{'description_' . $locale} ?: ($this->description_vn ?: $this->description_en);
    }
    protected $casts = [
        'status' => 'boolean',
        'hot' => 'boolean',
        'home' => 'boolean',
        'sale' => 'boolean',
        'quantity' => 'integer',
        'price' => 'decimal:2',
        'price_old' => 'decimal:2',
    ];
    /**
     * Scope query for low stock products.
     */
    public function scopeLowStock($query, int $threshold = 5)
    {
        return $query->where('status', true)->where('quantity', '<=', $threshold);
    }
    /**
     * Scope query for out of stock products.
     */
    public function scopeOutOfStock($query)
    {
        return $query->where('status', true)->where('quantity', '<=', 0);
    }
    public function cate()
    {
        return $this->belongsTo(CateProduct::class, 'category_id', 'id_cate_product');
    }
    public function brand()
    {
        return $this->belongsTo(Brand::class, 'brand_id', 'id_brand');
    }
}<?php
namespace App\Services;
use Exception;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\File;
use Illuminate\Support\Str;
use Intervention\Image\Facades\Image;
class ImageService
{
    /**
     * Lưu hình ảnh từ request vào thư mục chỉ định
     *
     * @param  \Illuminate\Http\Request  $request
     * @param  string  $imageFolder  Tên thư mục lưu ảnh
     * @param  string  $fieldName  Tên field chứa ảnh trong request
     * @param  array  $options  Các tùy chọn thêm
     *                          - mimeTypes: array - Các định dạng cho phép
     *                          - convertToWebp: bool - Có chuyển sang WebP không
     *                          - quality: int - Chất lượng ảnh WebP (1-100)
     * @return string|null Tên file ảnh đã lưu hoặc null nếu không có ảnh
     *
     * @throws \Exception
     */
    /**
     * Tạo đường dẫn con dạng {module}/{YYYY}/{MM}
     */
    private function getSubPath(string $imageFolder): string
    {
        $year = date('Y');
        $month = date('m');
        return "{$imageFolder}/{$year}/{$month}";
    }
    public function saveImage($request, string $imageFolder, string $fieldName, array $options = [])
    {
        // 1. Check if a new file is uploaded
        if ($request->hasFile($fieldName)) {
            try {
                $file = $request->file($fieldName);
                // Verify mime types if configured
                if (isset($options['mimeTypes']) && ! in_array($file->getMimeType(), $options['mimeTypes'])) {
                    throw new Exception('File format is not allowed');
                }
                // Subpath: {module}/{YYYY}/{MM}
                $subPath = $this->getSubPath($imageFolder);
                // Unique filename
                $fileName = $this->generateFileName($file, $options);
                // Ensure directory exists
                $this->ensureDirectoryExists($subPath);
                // Handle WebP conversion (default true unless disabled)
                $convertToWebp = $options['convertToWebp'] ?? true;
                if ($convertToWebp) {
                    $fileName = $this->handleWebpConversion($file, $subPath, $fileName, $options);
                } else {
                    $file->move(public_path("uploads/{$subPath}"), $fileName);
                }
                $relativePath = "uploads/{$subPath}/{$fileName}";
                // Auto register into Media table
                try {
                    $fullPath = public_path($relativePath);
                    $dimensions = null;
                    if (File::exists($fullPath)) {
                        $imgSize = @getimagesize($fullPath);
                        if ($imgSize && isset($imgSize[0]) && isset($imgSize[1])) {
                            $dimensions = "{$imgSize[0]}x{$imgSize[1]}";
                        }
                        \App\Models\Media::firstOrCreate(
                            ['path' => $relativePath],
                            [
                                'uuid' => (string) Str::uuid(),
                                'name' => pathinfo($file->getClientOriginalName(), PATHINFO_FILENAME),
                                'file_name' => $fileName,
                                'module' => Str::slug($imageFolder ?: 'general'),
                                'mime_type' => File::mimeType($fullPath) ?: 'image/webp',
                                'extension' => strtolower(pathinfo($fileName, PATHINFO_EXTENSION)),
                                'size' => File::size($fullPath),
                                'dimensions' => $dimensions,
                                'created_by' => auth()->id(),
                            ]
                        );
                    }
                } catch (\Throwable $mediaEx) {
                    // Suppress media logging failure
                }
                return $relativePath;
            } catch (Exception $e) {
                throw $e;
            }
        }
        // 2. Check if an existing media path was selected from Media Library
        $selectedPath = $request->input($fieldName . '_selected') ?: $request->input($fieldName);
        if (is_string($selectedPath) && !empty($selectedPath)) {
            $parsed = parse_url($selectedPath, PHP_URL_PATH) ?: $selectedPath;
            $cleanPath = ltrim($parsed, '/');
            if (str_starts_with($cleanPath, 'uploads/')) {
                return $cleanPath;
            }
        }
        return null;
    }
    /**
     * Cập nhật hình ảnh, hỗ trợ cả upload file mới và chọn từ Thư viện Media
     *
     * @param  \Illuminate\Http\Request  $request
     * @param  object  $model  Model chứa ảnh hiện tại
     * @param  string  $imageFolder  Tên thư mục lưu ảnh
     * @param  string  $fieldName  Tên field chứa ảnh trong request và model
     * @param  array  $options  Các tùy chọn thêm
     * @return string|null Tên file ảnh mới hoặc file ảnh hiện tại
     *
     * @throws \Exception
     */
    public function updateImage($request, $model, string $imageFolder, string $fieldName, array $options = [])
    {
        // 1. Explicit clear request
        if ($request->input($fieldName . '_clear') == '1' || $request->input($fieldName) === '') {
            if (!$request->hasFile($fieldName) && empty($request->input($fieldName . '_selected'))) {
                return null;
            }
        }
        // 2. If new file uploaded from PC
        if ($request->hasFile($fieldName)) {
            return $this->saveImage($request, $imageFolder, $fieldName, $options);
        }
        // 3. If selected from Media Library
        $selectedPath = $request->input($fieldName . '_selected') ?: $request->input($fieldName);
        if (is_string($selectedPath) && !empty($selectedPath)) {
            $parsed = parse_url($selectedPath, PHP_URL_PATH) ?: $selectedPath;
            $cleanPath = ltrim($parsed, '/');
            if (str_starts_with($cleanPath, 'uploads/')) {
                return $cleanPath;
            }
        }
        // 4. Retain existing model value
        return method_exists($model, 'getRawOriginal') ? $model->getRawOriginal($fieldName) : ($model->$fieldName ?? null);
    }
    /**
     * Xóa một hình ảnh
     *
     * @param  string|null  $fileName  Tên file cần xóa
     * @param  string  $imageFolder  Thư mục chứa file
     */
    public function deleteImage($fileName, string $imageFolder): bool
    {
        if (! $fileName) {
            return false;
        }
        $filePath = $this->getPhysicalPath($fileName, $imageFolder);
        if (File::exists($filePath)) {
            return File::delete($filePath);
        }
        return false;
    }
    /**
     * Lấy đường dẫn vật lý trên server từ tên file, đường dẫn tương đối hoặc URL tuyệt đối
     */
    private function getPhysicalPath($fileName, string $imageFolder): string
    {
        if (filter_var($fileName, FILTER_VALIDATE_URL)) {
            $path = parse_url($fileName, PHP_URL_PATH);
            $search = "uploads/";
            $pos = strpos($path, $search);
            if ($pos !== false) {
                $relativePath = substr($path, $pos);
                return public_path($relativePath);
            }
            return public_path(ltrim($path, '/'));
        }
        if (str_starts_with($fileName, 'uploads/')) {
            return public_path($fileName);
        }
        return public_path("uploads/{$imageFolder}/{$fileName}");
    }
    /**
     * Đảm bảo thư mục tồn tại, tạo mới nếu chưa có
     */
    private function ensureDirectoryExists(string $imageFolder): void
    {
        $path = public_path("uploads/{$imageFolder}");
        if (! File::exists($path)) {
            File::makeDirectory($path, 0755, true);
        }
    }
    private function generateFileName(UploadedFile $file, array $options = []): string
    {
        $prefix = $options['prefix'] ?? '';
        // Đoán extension thật dựa trên mime type, nếu không đoán được mới dùng getClientOriginalExtension()
        $extension = $file->guessExtension() ?: $file->getClientOriginalExtension();
        // Băm tên file để tránh trùng đè file và an toàn I/O
        $hashName = md5($file->getClientOriginalName() . time() . Str::random(10));
        $fileName = $hashName . '.' . $extension;
        return $prefix ? $prefix.'-'.$fileName : $fileName;
    }
    /**
     * Chuyển đổi ảnh sang định dạng WebP (hoặc fallback lưu file gốc)
     *
     * @param  UploadedFile|string  $file  Đối tượng file upload hoặc đường dẫn vật lý
     * @param  string  $targetPath  Đường dẫn file đích (webp)
     * @param  int  $quality  Chất lượng ảnh (1-100)
     * @return string|bool Tên file thực tế đã lưu (ví dụ: 'hash.webp' hoặc 'hash.jpg'), hoặc false nếu lỗi
     */
    public function convertToWebp(UploadedFile|string $file, string $targetPath, int $quality = 80, int $maxWidth = 1600): string|bool
    {
        // 1. Phân loại đối tượng file và lấy đường dẫn vật lý
        if ($file instanceof UploadedFile) {
            $sourcePath = $file->getPathname();
        } else {
            $sourcePath = (string) $file;
        }
        // 2. Kiểm tra file nguồn tồn tại
        if (empty($sourcePath) || ! file_exists($sourcePath)) {
            return false;
        }
        // 3. Tăng giới hạn bộ nhớ PHP lên 1024M để xử lý ảnh độ phân giải siêu cao (40MP+)
        @ini_set('memory_limit', '1024M');
        // 4. Kiểm tra kích thước file (cho phép tối đa 100MB)
        $fileSize = filesize($sourcePath);
        if ($fileSize > 100 * 1024 * 1024) { // 100MB
            return $this->fallbackToOriginal($file, $targetPath);
        }
        // 5. Đảm bảo thư mục đích tồn tại và có quyền ghi
        $targetDir = dirname($targetPath);
        if (! File::exists($targetDir)) {
            File::makeDirectory($targetDir, 0755, true);
        }
        if (! is_writable($targetDir)) {
            return $this->fallbackToOriginal($file, $targetPath);
        }
        // 6. Xử lý convert WebP với Intervention Image
        $image = null;
        try {
            $image = Image::make($sourcePath);
            if (! $image) {
                return $this->fallbackToOriginal($file, $targetPath);
            }
            // Tự động resize theo giới hạn độ phân giải tối đa (giữ aspect ratio & upsize constraint)
            if ($image->width() > $maxWidth || $image->height() > $maxWidth) {
                $image->resize($maxWidth, $maxWidth, function ($constraint) {
                    $constraint->aspectRatio();
                    $constraint->upsize();
                });
            }
            // Encode sang WebP
            $result = $image->encode('webp', $quality);
            $result->save($targetPath);
            if (! file_exists($targetPath)) {
                return $this->fallbackToOriginal($file, $targetPath);
            }
            return pathinfo($targetPath, PATHINFO_BASENAME);
        } catch (\Throwable $e) {
            return $this->fallbackToOriginal($file, $targetPath);
        } finally {
            if ($image && method_exists($image, 'destroy')) {
                $image->destroy();
            }
        }
    }
    /**
     * Fallback lưu file gốc chính xác định dạng đuôi file khi WebP thất bại
     *
     * @param  UploadedFile|string  $file
     * @param  string  $targetPath
     * @return string|bool Tên file đã lưu thành công hoặc false
     */
    private function fallbackToOriginal(UploadedFile|string $file, string $targetPath): string|bool
    {
        try {
            if ($file instanceof UploadedFile) {
                $sourcePath = $file->getPathname();
                $originalExt = $file->getClientOriginalExtension() ?: ($file->guessExtension() ?: 'jpg');
            } else {
                $sourcePath = (string) $file;
                $originalExt = pathinfo($sourcePath, PATHINFO_EXTENSION) ?: 'jpg';
            }
            if (empty($sourcePath) || ! file_exists($sourcePath)) {
                return false;
            }
            $fallbackFileName = pathinfo($targetPath, PATHINFO_FILENAME) . '.' . strtolower($originalExt);
            $fallbackPath = dirname($targetPath) . '/' . $fallbackFileName;
            if ($file instanceof UploadedFile) {
                $file->move(dirname($targetPath), $fallbackFileName);
            } else {
                copy($sourcePath, $fallbackPath);
            }
            if (file_exists($fallbackPath)) {
                return $fallbackFileName;
            }
        } catch (Exception $copyError) {
            // Fallback copy failed
        }
        return false;
    }
    /**
     * Get PHP memory limit in bytes
     */
    private function getMemoryLimit(): int
    {
        $memoryLimit = ini_get('memory_limit');
        if ($memoryLimit == -1) {
            return PHP_INT_MAX;
        }
        $unit = strtolower(substr($memoryLimit, -1));
        $value = (int) $memoryLimit;
        switch ($unit) {
            case 'g':
                $value *= 1024;
            case 'm':
                $value *= 1024;
            case 'k':
                $value *= 1024;
        }
        return $value;
    }
    /**
     * Xử lý chuyển đổi và lưu ảnh dạng WebP
     *
     * @param  UploadedFile  $file  File ảnh gốc
     * @param  string  $subPath  Thư mục con lưu ảnh
     * @param  string  $fileName  Tên file (sẽ được đổi đuôi thành .webp hoặc giữ nguyên nếu fallback)
     * @param  array  $options  Tùy chọn (quality)
     * @return string Tên file thực tế đã lưu
     *
     * @throws Exception
     */
    private function handleWebpConversion(UploadedFile $file, string $subPath, string $fileName, array $options = []): string
    {
        $this->ensureDirectoryExists($subPath);
        $webpFileName = pathinfo($fileName, PATHINFO_FILENAME).'.webp';
        $targetPath = public_path("uploads/{$subPath}/{$webpFileName}");
        // Auto determine optimal dimension & quality per module/context (Rule 20)
        // Sliders/Banners: max 1600px, quality 80 (<100KB). Products/News/Cards: max 800px, quality 75 (<60KB)
        $isHero = str_contains(strtolower($subPath), 'slider') || str_contains(strtolower($subPath), 'banner');
        $maxWidth = $options['maxWidth'] ?? ($isHero ? 1600 : 800);
        $quality = $options['quality'] ?? ($isHero ? 80 : 75);
        $savedFileName = $this->convertToWebp($file, $targetPath, $quality, $maxWidth);
        if (! $savedFileName) {
            throw new Exception('Không thể chuyển đổi hoặc lưu ảnh');
        }
        return $savedFileName;
    }
    /**
     * Process individual media file in detail gallery (supports both images and short videos)
     */
    private function processDetailMediaFile($file, string $subPath, array $options = []): ?string
    {
        $videoExtensions = ['mp4', 'webm', 'mov', 'ogg'];
        $ext = strtolower($file->getClientOriginalExtension());
        if (in_array($ext, $videoExtensions)) {
            $this->ensureDirectoryExists($subPath);
            $videoName = 'video_' . \Illuminate\Support\Str::random(10) . '_' . time() . '.' . $ext;
            $file->move(public_path("uploads/{$subPath}"), $videoName);
            return "uploads/{$subPath}/{$videoName}";
        }
        $fileName = $this->generateFileName($file, $options);
        $this->ensureDirectoryExists($subPath);
        if (isset($options['convertToWebp']) && $options['convertToWebp']) {
            $fileName = $this->handleWebpConversion($file, $subPath, $fileName, $options);
        } else {
            $file->move(public_path("uploads/{$subPath}"), $fileName);
        }
        return "uploads/{$subPath}/{$fileName}";
    }
    /**
     * Handle multiple media detail files for create/store operations
     */
    public function handleDetailImages($request, $imageFolder, array $options = [])
    {
        $files = [];
        // Support pre-selected media paths from media library
        $selected = $request->input('selected_detail_images', []);
        if (is_string($selected)) {
            $selected = json_decode($selected, true) ?: [];
        }
        if (is_array($selected)) {
            foreach ($selected as $path) {
                if (is_string($path) && str_starts_with($path, 'uploads/')) {
                    $files[] = $path;
                }
            }
        }
        if ($request->hasFile('image_detail')) {
            $subPath = $this->getSubPath($imageFolder);
            foreach ($request->file('image_detail') as $file) {
                try {
                    $savedPath = $this->processDetailMediaFile($file, $subPath, $options);
                    if ($savedPath) {
                        $files[] = $savedPath;
                    }
                } catch (Exception $e) {
                    continue;
                }
            }
        }
        return json_encode($files);
    }
    /**
     * Handle multiple media detail files for edit/update operations
     */
    public function updateDetailImages($request, $model, string $imageFolder, string $fieldName = 'image_detail', array $options = [])
    {
        $existingImages = json_decode($model->$fieldName, true) ?: [];
        $keptImages = $request->input('kept_images', []);
        if (is_string($keptImages)) {
            $keptImages = json_decode($keptImages, true) ?: [];
        }
        $filteredExistingImages = [];
        foreach ($keptImages as $item) {
            if (in_array($item, $existingImages)) {
                $filteredExistingImages[] = $item;
            }
        }
        // Support newly added media paths from media library
        $selected = $request->input('selected_detail_images', []);
        if (is_string($selected)) {
            $selected = json_decode($selected, true) ?: [];
        }
        if (is_array($selected)) {
            foreach ($selected as $path) {
                if (is_string($path) && str_starts_with($path, 'uploads/') && !in_array($path, $filteredExistingImages)) {
                    $filteredExistingImages[] = $path;
                }
            }
        }
        $newImages = [];
        if ($request->hasFile('image_detail')) {
            $subPath = $this->getSubPath($imageFolder);
            foreach ($request->file('image_detail') as $file) {
                try {
                    $savedPath = $this->processDetailMediaFile($file, $subPath, $options);
                    if ($savedPath) {
                        $newImages[] = $savedPath;
                    }
                } catch (Exception $e) {
                    continue;
                }
            }
        }
        $allImages = array_merge($filteredExistingImages, $newImages);
        return json_encode($allImages);
    }
    /**
     * Xóa những hình ảnh không được sử dụng
     */
    private function cleanupUnusedImages($existingImages, $keptImages, $imageFolder)
    {
        $imagesToDelete = array_diff($existingImages, $keptImages);
        foreach ($imagesToDelete as $imageToDelete) {
            $this->deleteImage($imageToDelete, $imageFolder);
        }
    }
    /**
     * Lưu và chuyển đổi ảnh sang WebP
     */
    public function saveImageAsWebp($request, string $imageFolder, string $fieldName, array $options = [])
    {
        if (! $request->hasFile($fieldName)) {
            return null;
        }
        try {
            $file = $request->file($fieldName);
            // Kiểm tra mime type
            if (isset($options['mimeTypes']) && ! in_array($file->getMimeType(), $options['mimeTypes'])) {
                throw new Exception('File không đúng định dạng cho phép');
            }
            $subPath = $this->getSubPath($imageFolder);
            $fileName = $this->generateFileName($file, $options);
            $savedFileName = $this->handleWebpConversion($file, $subPath, $fileName, $options);
            return "uploads/{$subPath}/{$savedFileName}";
        } catch (Exception $e) {
            throw $e;
        }
    }
}
